{
  "decision": "covered",
  "policy_quotes": [
    "Open and laparoscopic Roux-en-Y gastric bypass (RYGBP) [...] are covered for Medicare beneficiaries who have a body-mass index ≥ 35, have at least one co-morbidity related to obesity, and have been previously unsuccessful with medical treatment for obesity.",
    "Effective for services performed on and after February 12, 2009, the Centers for Medicare & Medicaid Services (CMS) determines that Type 2 diabetes mellitus is a co-morbidity for purposes of this NCD."
  ],
  "missing_documentation": [],
  "rationale": "The beneficiary meets all coverage criteria for laparoscopic Roux-en-Y gastric bypass: BMI of 35.0 kg/m² (exactly at the threshold), type 2 diabetes mellitus (a recognized co-morbidity), and documented failure of medical treatment through a supervised weight management program with medication trial. The procedure is explicitly covered under NCD 100.1, and facility certification requirements were lifted after 2013, so no additional documentation is needed."
}

{
  "decision": "not_covered",
  "policy_quotes": [
    "Effective for services performed on and after February 21, 2006, Open and laparoscopic Roux-en-Y gastric bypass (RYGBP), open and laparoscopic Biliopancreatic Diversion with Duodenal Switch (BPD/DS) or Gastric Reduction Duodenal Switch (BPD/GRDS), and laparoscopic adjustable gastric banding (LAGB) are covered for Medicare beneficiaries [...] only when performed at facilities that are: (1) certified by the American College of Surgeons as a Level 1 Bariatric Surgery Center (program standards and requirements in effect on February 15, 2006); or (2) certified by the American Society for Bariatric Surgery as a Bariatric Surgery Center of Excellence (program standards and requirements in effect on February 15, 2006)."
  ],
  "missing_documentation": [],
  "rationale": "The patient meets the clinical criteria for bariatric surgery with BMI ≥35, co-morbid obstructive sleep apnea, and documented failure of medical treatment. However, the requested open biliopancreatic diversion with duodenal switch is explicitly covered only when performed at a certified facility per the NCD. The case states the community hospital lacks certification by either the American College of Surgeons or the American Society for Bariatric Surgery, violating the facility requirement and rendering the service non-covered."
}

{
  "decision": "not_covered",
  "policy_quotes": ["Effective for services performed on and after February 21, 2006, Open and laparoscopic Roux-en-Y gastric bypass (RYGBP) [...] are covered for Medicare beneficiaries who have a body-mass index ≥ 35"],
  "missing_documentation": [],
  "rationale": "The policy explicitly requires a body-mass index (BMI) of ≥ 35 kg/m² for coverage of laparoscopic Roux-en-Y gastric bypass. The patient's documented BMI is 34.6 kg/m², which does not meet this threshold. Although the patient has qualifying comorbidities (type 2 diabetes and hypertension) and documented unsuccessful medical treatment, the BMI criterion is not satisfied, making the service non-covered."
}

{
