{
  "decision": "covered",
  "policy_quotes": [
    "Effective for claims with dates of service on or after January 27, 2016, allogeneic HSCT for multiple myeloma is covered by Medicare only for beneficiaries with Durie-Salmon Stage II or III multiple myeloma, or International Staging System (ISS) Stage II or Stage III multiple myeloma, and participating in an approved prospective clinical study that meets the criteria below.",
    "All CMS-approved clinical studies and registries must adhere to the below listed standards of scientific integrity and relevance to the Medicare population as listed in section g.",
    "The clinical research studies and registries are registered on the www.ClinicalTrials.gov website by the principal sponsor/investigator prior to the enrollment of the first study subject."
  ],
  "missing_documentation": [],
  "rationale": "The patient meets all coverage criteria for allogeneic HSCT for multiple myeloma under NCD 110.23. He has ISS Stage II disease, is enrolled in a CMS-approved prospective clinical study registered on ClinicalTrials.gov, and the study protocol addresses required outcomes including graft-versus-host disease, transplant-related adverse events, and overall survival with appropriate statistical adjustments. No required documentation appears to be missing based on the case facts provided."
}

{
  "decision": "not_covered",
  "policy_quotes": [
    "Effective for claims with dates of service on or after January 27, 2016, allogeneic HSCT for multiple myeloma is covered by Medicare only for beneficiaries with Durie-Salmon Stage II or III multiple myeloma, or International Staging System (ISS) Stage II or Stage III multiple myeloma, and participating in an approved prospective clinical study that meets the criteria below."
