}

{
  "decision": "not_covered",
  "policy_quotes": ["Effective for claims with dates of service on or after January 27, 2016, allogeneic HSCT for myelofibrosis (MF) is covered by Medicare only for beneficiaries with Dynamic International Prognostic Scoring System (DIPSSplus) Intermediate-2 or High primary or secondary MF and participating in an approved prospective clinical study."],
