  "policy_quotes": ["Patients with acute cardiac allograft rejection whose disease is refractory to standard immunosuppressive drug treatment"],
  "missing_documentation": [],
  "rationale": "The policy requires that acute cardiac allograft rejection must be refractory to standard immunosuppressive drug treatment for coverage. The patient has not yet received any augmented immunosuppression (such as pulse corticosteroids) for this first rejection episode, so the disease cannot be considered refractory to standard treatment. Since the patient has not failed standard therapy, the coverage criterion is not met."
}

{
  "decision": "not_covered",
  "policy_quotes": ["Patients with acute cardiac allograft rejection whose disease is refractory to standard immunosuppressive drug treatment", "All other indications for extracorporeal photopheresis not otherwise indicated above as covered remain non-covered"],
  "missing_documentation": [],
  "rationale": "The NCD specifically covers extracorporeal photopheresis for acute cardiac allograft rejection refractory to standard treatment, but this patient has kidney allograft rejection. The policy does not list renal allograft rejection as a covered indication, and Section C explicitly states that all other indications not specifically covered remain non-covered. The documentation clearly shows the patient has refractory kidney rejection, which falls under the non-covered indications."
}

{
  "decision": "covered",
  "policy_quotes": ["Patients with chronic graft versus host disease whose disease is refractory to standard immunosuppressive drug treatment."],
  "missing_documentation": [],
  "rationale": "The patient has chronic graft-versus-host disease that is refractory to standard immunosuppressive treatment including prednisone, tacrolimus, and sirolimus. This meets the nationally covered indication for extracorporeal photopheresis effective December 19, 2006, as the disease has not responded to standard therapy."
}

{
  "decision": "not_covered",
  "policy_quotes": ["Patients with chronic graft versus host disease whose disease is refractory to standard immunosuppressive drug treatment"],
  "missing_documentation": [],
  "rationale": "The policy only covers extracorporeal photopheresis for chronic graft-versus-host disease that is refractory to standard immunosuppressive treatment. The patient has acute graft-versus-host disease (grade III), which is explicitly excluded from coverage under this NCD. The documentation confirms the condition is acute rather than chronic, making this a nationally non-covered indication."
}

{
  "decision": "insufficient_documentation",
  "policy_quotes": ["Patients with chronic graft versus host disease whose disease is refractory to standard immunosuppressive drug treatment."],
  "missing_documentation": ["Documentation of prior standard immunosuppressive drug treatment", "Documentation of disease being refractory to standard immunosuppressive drug treatment"],
  "rationale": "The patient has chronic graft-versus-host disease, which is a covered indication under NCD 110.4(B)(2). However, coverage requires that the disease be refractory to standard immunosuppressive drug treatment. The referral note lacks any documentation of what immunosuppressive treatments were attempted or how the disease responded to them, making it impossible to determine if the coverage criterion is met."
}

{
  "decision": "not_covered",
