}

{
  "decision": "insufficient_documentation",
  "policy_quotes": ["Palliative treatment of skin manifestations of cutaneous T-cell lymphoma that has not responded to other therapy."],
  "missing_documentation": ["Documentation showing the patient's cutaneous T-cell lymphoma has not responded to other therapy"],
  "rationale": "The patient has mycosis fungoides (a form of cutaneous T-cell lymphoma) which is a covered indication under the NCD. However, the policy requires documentation that the condition has not responded to other therapy. While the request mentions 'prior therapies per outside records,' these records were not received and are absent from the submitted documentation."
}

{
  "decision": "covered",
  "policy_quotes": [
    "Nonunion of long bone fractures;",
    "Effective September 15, 1980, nonunion of long bone fractures is considered to exist only after 6 or more months have elapsed without healing of the fracture.",
    "Effective April 1, 2000, nonunion of long bone fractures is considered to exist only when serial radiographs have confirmed that fracture healing has ceased for 3 or more months prior to starting treatment with the electrical osteogenic stimulator. Serial radiographs must include a minimum of 2 sets of radiographs, each including multiple views of the fracture site, separated by a minimum of 90 days."
  ],
  "missing_documentation": [],
  "rationale": "The tibial shaft fracture is a long bone nonunion, meeting the covered indication. The fracture is 8 months old, exceeding the 6-month threshold, and serial radiographs taken 105 days apart confirm healing cessation for over 3 months with multiple views. The noninvasive electrical stimulator is appropriately ordered for this documented nonunion case."
}

{
  "decision": "not_covered",
  "policy_quotes": [
    "Nonunion fractures of the skull, vertebrae and those that are tumor-related are excluded from coverage.",
    "Ultrasonic osteogenic stimulators for fresh fractures and delayed unions remains non-covered."
  ],
  "missing_documentation": [],
  "rationale": "The scaphoid is a carpal bone of the wrist, not a long bone, and the policy explicitly excludes coverage for nonunion fractures of the skull and vertebrae. While not explicitly listed, CMS coverage for osteogenic stimulators is historically limited to long bones and spinal fusions, with scaphoid fractures falling outside nationally covered indications. Additionally, the policy states ultrasonic stimulators remain non-covered for delayed unions, and a 7-month scaphoid fracture without healing may be classified as a delayed union rather than a nonunion in this context."
}

{
  "decision": "not_covered",
  "policy_quotes": [
    "Effective September 15, 1980, nonunion of long bone fractures is considered to exist only after 6 or more months have elapsed without healing of the fracture.",
    "Effective April 1, 2000, nonunion of long bone fractures is considered to exist only when serial radiographs have confirmed that fracture healing has ceased for 3 or more months prior to starting treatment with the electrical osteogenic stimulator."
  ],
  "missing_documentation": [],
  "rationale": "The policy requires that nonunion of long bone fractures must exist for at least 6 months before treatment with an electrical osteogenic stimulator can be covered. Here, only 4 months have elapsed since the surgery, failing to meet the minimum time requirement. Additionally, while the radiographs show no progression over 95 days, the treatment cannot start until at least 6 months have passed without healing, regardless of radiographic findings."
}

{
  "decision": "insufficient_documentation",
  "policy_quotes": [
    "Serial radiographs must include a minimum of 2 sets of radiographs, each including multiple views of the fracture site, separated by a minimum of 90 days.",
    "Each radiograph set must include multiple views of the fracture site accompanied with a written interpretation by a physician stating that there has been no clinically significant evidence of fracture healing between the 2 sets of radiographs"
  ],
  "missing_documentation": [
    "Radiographs separated by at least 90 days (current separation is only 60 days)",
    "Written physician interpretation stating no clinically significant evidence of healing between radiograph sets"
  ],
  "rationale": "The policy requires radiographs to be separated by a minimum of 90 days to demonstrate cessation of healing, but the case shows only 60 days between studies. Additionally, while multiple views were obtained, there is no documentation of a written physician interpretation confirming no clinically significant healing between the two sets. These missing elements prevent confirmation that nonunion criteria are fully met."
}

{
  "decision": "not_covered",
  "policy_quotes": [
    "Effective July 1, 1996, as an adjunct to spinal fusion surgery for patients at high risk of pseudarthrosis due to previously failed spinal fusion at the same site or for those undergoing multiple level fusion."
